/* Host tests of the bf16 cuBLAS variants and their runtime (review section 5, H1-H7 and H9), without
 * a GPU: the variants generated by vf-fwdgen from stand-in libraries are called through the CUDA 13
 * names; the stand-ins for libcuda.so.1, libcublas.so.12 and libcublasLt.so.12 record what reaches
 * them (stub_*.c). tests/forward/bf16.sh builds everything and runs each mode in its own process:
 *   host_test all          H1 (forwarding and call sequences), H2, H3, H4, H5, H6, H7
 *   host_test rule         the paths' rule, a table of (n, m k, k) classes and the path or reason of each
 *   host_test release-gate the release runtime with VF_BF16_TC_MIN_K=1024: the variable is not read there
 *   host_test skinny       the skinny path alone (VF_CUBLAS_BF16_SKINNY=1): its bounds
 *   host_test off          no switch: every call forwarded, nothing of the runtime loaded
 *   host_test safe         VF_SAFE=1 with VF_CUBLAS_BF16_TC=1: tensor-core calls forwarded, skinny calls served
 *   host_test notsafe      VF_SAFE set to anything but 1, with VF_CUBLAS_BF16_TC=1: tensor-core calls served
 *   host_test lazy         nothing made with a handle; the module at the first call a path serves, the
 *                          tensor-core path's pool and cuBLASLt handle at its first call, in relaxed mode
 *   host_test inject STEP  a failure injected at STEP (VF_BF16_INJECT): forwarded, or status 13
 *   host_test noruntime    the runtime missing: forwarded, said once, no abort (H9)
 * Prints "ok <mode>" when every check passes. */
#define _GNU_SOURCE
#include "stub.h"
#include "../../../crates/vf-fwdgen/bf16tc/abi.h"
#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int failures;
#define CHECK(cond, ...)                                 \
    do {                                                 \
        if (!(cond)) {                                   \
            ++failures;                                  \
            printf("FAIL  %s:%d: ", __FILE__, __LINE__); \
            printf(__VA_ARGS__);                         \
            printf("\n");                                \
        }                                                \
    } while (0)

/* The variants' exports, as a program built against CUDA 13 calls them. */
static struct {
    __typeof__(cublasCreate_v2) *Create;
    __typeof__(cublasDestroy_v2) *Destroy;
    __typeof__(cublasSetStream_v2) *SetStream;
    __typeof__(cublasSetWorkspace_v2) *SetWorkspace;
    __typeof__(cublasSetPointerMode_v2) *SetPointerMode;
    __typeof__(cublasSetMathMode) *SetMathMode;
    __typeof__(cublasGemmEx) *GemmEx;
    __typeof__(cublasGemmEx_64) *GemmEx64;
    __typeof__(cublasGemmStridedBatchedEx) *GemmSB;
    __typeof__(cublasLtCreate) *LtCreate;
    __typeof__(cublasLtMatmul) *LtMatmul;
    __typeof__(cublasLtMatmulDescCreate) *DescCreate;
    __typeof__(cublasLtMatmulDescSetAttribute) *DescSet;
    __typeof__(cublasLtMatmulDescDestroy) *DescDestroy;
    __typeof__(cublasLtMatrixLayoutCreate) *LayoutCreate;
    __typeof__(cublasLtMatrixLayoutSetAttribute) *LayoutSet;
    __typeof__(cublasLtMatrixLayoutDestroy) *LayoutDestroy;
} v;
static int (*rt_counters)(int, unsigned long long *, int);

static void open_variants(const char *dir)
{
    char p[4096];
    snprintf(p, sizeof p, "%s/libcublas.so.13", dir);
    void *b = dlopen(p, RTLD_NOW | RTLD_LOCAL);
    snprintf(p, sizeof p, "%s/libcublasLt.so.13", dir);
    void *l = dlopen(p, RTLD_NOW | RTLD_LOCAL);
    if (!b || !l) {
        printf("FAIL  cannot open the variants in %s: %s\n", dir, dlerror());
        exit(1);
    }
#define B(f, n) *(void **)&v.f = dlsym(b, n)
#define L(f, n) *(void **)&v.f = dlsym(l, n)
    B(Create, "cublasCreate_v2");
    B(Destroy, "cublasDestroy_v2");
    B(SetStream, "cublasSetStream_v2");
    B(SetWorkspace, "cublasSetWorkspace_v2");
    B(SetPointerMode, "cublasSetPointerMode_v2");
    B(SetMathMode, "cublasSetMathMode");
    B(GemmEx, "cublasGemmEx");
    B(GemmEx64, "cublasGemmEx_64");
    B(GemmSB, "cublasGemmStridedBatchedEx");
    L(LtCreate, "cublasLtCreate");
    L(LtMatmul, "cublasLtMatmul");
    L(DescCreate, "cublasLtMatmulDescCreate");
    L(DescSet, "cublasLtMatmulDescSetAttribute");
    L(DescDestroy, "cublasLtMatmulDescDestroy");
    L(LayoutCreate, "cublasLtMatrixLayoutCreate");
    L(LayoutSet, "cublasLtMatrixLayoutSetAttribute");
    L(LayoutDestroy, "cublasLtMatrixLayoutDestroy");
}

static void open_runtime(void)
{
    void *rt = dlopen("libvf_cublas_bf16.so", RTLD_NOW | RTLD_NOLOAD);
    if (rt) *(void **)&rt_counters = dlsym(rt, "vf_bf16_test_counters");
}

/* ---- the event log ---- */
static char *ev;
static void take(void)
{
    free(ev);
    ev = stub_take_events();
}
static int count(const char *prefix)
{
    int n = 0;
    for (const char *p = ev; p && *p;) {
        if (!strncmp(p, prefix, strlen(prefix))) ++n;
        p = strchr(p, '\n');
        if (p) ++p;
    }
    return n;
}
/* The i-th line beginning with prefix (static buffer), or NULL. */
static const char *line(const char *prefix, int i)
{
    static char buf[4096];
    for (const char *p = ev; p && *p;) {
        const char *e = strchr(p, '\n');
        if (!strncmp(p, prefix, strlen(prefix)) && i-- == 0) {
            const size_t n = e ? (size_t)(e - p) : strlen(p);
            memcpy(buf, p, n < sizeof buf - 1 ? n : sizeof buf - 1);
            buf[n < sizeof buf - 1 ? n : sizeof buf - 1] = 0;
            return buf;
        }
        p = e ? e + 1 : NULL;
    }
    return NULL;
}
static const char *field(const char *l, const char *key, char *out, size_t n)
{
    const char *p = l ? strstr(l, key) : NULL;
    if (!p) return "";
    p += strlen(key);
    size_t i = 0;
    while (p[i] && p[i] != ' ' && i + 1 < n) out[i] = p[i], ++i;
    out[i] = 0;
    return out;
}
/* The argument structure of a launch event. */
static void launch_args(const char *l, void *out, size_t size)
{
    const char *p = strstr(l, "args=");
    memset(out, 0, size);
    if (!p) return;
    p += 5;
    for (size_t i = 0; i < size && p[2 * i] && p[2 * i + 1]; ++i) {
        unsigned x;
        sscanf(p + 2 * i, "%2x", &x);
        ((unsigned char *)out)[i] = (unsigned char)x;
    }
}

/* ---- counters ---- */
enum { R_TYPES, R_ALGO, R_BATCH, R_RANGE, R_SHAPE, R_ARGS, R_DOMAIN, R_SEQ, R_BUILD, R_K, R_SHORT_K, R_HANDLE, R_CONTEXT, R_MATH,
       R_POINTER, R_ALPHA0, R_ALIAS, R_LTATTR, R_PLAN, R_CAPTURED, R_ALLOC, R_LAUNCH, R_N };
enum { API_GEMMEX, API_GEMMEX64, API_SB, API_SB64, API_LT };
typedef struct {
    unsigned long long v[4 + R_N];
} Counts;
static Counts counts(int api)
{
    Counts c;
    memset(&c, 0, sizeof c);
    if (rt_counters) rt_counters(api, c.v, 4 + R_N);
    return c;
}

/* ---- a product through the legacy API ---- */
static cublasHandle_t H;
static CUstream S1 = (CUstream)0x5101, S2 = (CUstream)0x5102;
/* Distinct, 256-byte aligned "device" addresses (never dereferenced: the stand-ins compute nothing). */
#define DEV(x) ((void *)(uintptr_t)(0x7f0000000000ull + (unsigned long long)(x) * 0x10000000ull))

typedef struct {
    int ta, tb, m, n, k;
    cudaDataType at, bt, ct;
    int lda, ldb, ldc;
    cublasComputeType_t compute;
    cublasGemmAlgo_t algo;
    float alpha, beta;
    const void *A, *B;
    void *C;
} G;

static G gemm(int ta, int tb, int m, int n, int k)
{
    G g = {ta, tb, m, n, k, CUDA_R_16BF, CUDA_R_16BF, CUDA_R_32F, ta ? k : m, tb ? n : k, m,
           CUBLAS_COMPUTE_32F, CUBLAS_GEMM_DEFAULT, 1.0f, 0.0f, DEV(1), DEV(2), DEV(3)};
    return g;
}

static cublasStatus_t call(const G *g)
{
    return v.GemmEx(H, (cublasOperation_t)g->ta, (cublasOperation_t)g->tb, g->m, g->n, g->k,
                    &g->alpha, g->A, g->at, g->lda, g->B, g->bt, g->ldb, &g->beta, g->C, g->ct, g->ldc, g->compute,
                    g->algo);
}

/* Forwarded: one 12.9 call with every argument as given, nothing of the runtime's, the reason. */
static void expect_forwarded(const char *what, const G *g, int reason)
{
    const Counts c0 = counts(API_GEMMEX);
    take();
    const cublasStatus_t st = call(g);
    take();
    const Counts c1 = counts(API_GEMMEX);
    char want[512];
    snprintf(want, sizeof want, "gemmex handle=%p ta=%d tb=%d m=%d n=%d k=%d lda=%d ldb=%d ldc=%d alpha=%p A=%p at=%d "
             "B=%p bt=%d beta=%p C=%p ct=%d compute=%d algo=%d ", (void *)H, g->ta, g->tb, g->m, g->n, g->k, g->lda,
             g->ldb, g->ldc, (void *)&g->alpha, g->A, g->at, g->B, g->bt, (void *)&g->beta, g->C, g->ct, g->compute,
             g->algo);
    CHECK(st == 0, "%s: status %d", what, st);
    CHECK(count("gemmex ") == 1 && !strncmp(line("gemmex ", 0), want, strlen(want)),
          "%s: not one call of 12.9's cublasGemmEx with the same arguments:\n      want %s\n      got  %s", what, want,
          line("gemmex ", 0) ? line("gemmex ", 0) : "(none)");
    CHECK(count("launch") == 0 && count("alloc") == 0 && count("ltmatmul") == 0, "%s: the runtime did work", what);
    CHECK(!rt_counters || c1.v[4 + reason] - c0.v[4 + reason] == 1, "%s: not counted as reason %d", what, reason);
}

/* Served by the skinny path: one launch, nothing forwarded. */
static void expect_skinny(const char *what, const G *g, const char *kernel)
{
    take();
    const cublasStatus_t st = call(g);
    take();
    CHECK(st == 0, "%s: status %d", what, st);
    CHECK(count("gemmex ") == 0 && count("alloc") == 0, "%s: forwarded or allocated", what);
    CHECK(count("launch ") == 1 && strstr(line("launch ", 0), kernel), "%s: not one launch of %s:\n%s", what, kernel, ev);
}

/* ---- H1: forwarded with identical arguments ---- */
static void h1_forwarded(void)
{
    G g;
    g = gemm(1, 0, 1536, 128, 4096); g.compute = CUBLAS_COMPUTE_32F_PEDANTIC; expect_forwarded("pedantic compute", &g, R_TYPES);
    g = gemm(1, 0, 1536, 128, 4096); g.at = CUDA_R_16F; expect_forwarded("fp16 A", &g, R_TYPES);
    g = gemm(1, 0, 1536, 128, 4096); g.ct = CUDA_R_16F; expect_forwarded("fp16 C", &g, R_TYPES);
    g = gemm(1, 0, 1536, 1, 1536); expect_forwarded("n = 1", &g, R_SHAPE);
    g = gemm(1, 0, 1536, 512, 8); expect_forwarded("k = 8", &g, R_SHAPE);
    g = gemm(1, 0, 0, 512, 1536); g.ldc = 1; expect_forwarded("m = 0", &g, R_SHAPE);
    g = gemm(0, 0, 1536, 512, 1536); g.lda = 1000; expect_forwarded("lda < m", &g, R_ARGS);
    g = gemm(1, 0, 1536, 128, 4096); g.C = NULL; expect_forwarded("C NULL", &g, R_ARGS);
    g = gemm(1, 0, 1536, 128, 4096); g.ta = 7; expect_forwarded("unknown operation", &g, R_ARGS);
    g = gemm(1, 0, 1536, 128, 4096); g.algo = CUBLAS_GEMM_DEFAULT_TENSOR_OP + 3; expect_forwarded("ALGO3_TENSOR_OP", &g, R_ALGO); /* H2 */
    g = gemm(1, 0, 1536, 128, 4096); g.algo = (cublasGemmAlgo_t)0; expect_forwarded("ALGO0", &g, R_ALGO);       /* H2 */
    g = gemm(1, 0, 1536, 128, 4096); g.algo = (cublasGemmAlgo_t)23; expect_forwarded("ALGO23", &g, R_ALGO);     /* H2 */
    g = gemm(1, 0, 1536, 128, 4096); g.alpha = 0.0f; expect_forwarded("alpha = 0", &g, R_ALPHA0);
    g = gemm(1, 0, 1536, 128, 4096); g.C = (void *)((const char *)g.A + 64); expect_forwarded("C overlaps A", &g, R_ALIAS);
    g = gemm(1, 0, 64, 40, 16392); expect_forwarded("k = 16392 on the tensor-core path", &g, R_K);            /* H3 */
    g = gemm(1, 0, 64, 20, 512); expect_forwarded("TN m k < 2^20, n = 20, m < 448", &g, R_SEQ);                /* H3 */
    /* (m k < 2^20 and n < 32: the tensor-core path's gate does not take them) */
    g = gemm(1, 0, 384, 8, 1536); expect_forwarded("TN m = 384 (12.9: gemmSN)", &g, R_SEQ);
    g = gemm(1, 0, 512, 8, 1536); g.A = (const char *)g.A + 2; expect_forwarded("TN misaligned A", &g, R_SEQ);
    g = gemm(1, 0, 512, 8, 1536); g.ldc = 516; expect_forwarded("TN ldc not a multiple of 8", &g, R_SEQ);
    v.SetMathMode(H, CUBLAS_PEDANTIC_MATH);
    g = gemm(1, 0, 1536, 128, 4096); expect_forwarded("pedantic math mode", &g, R_MATH);
    v.SetMathMode(H, CUBLAS_DEFAULT_MATH);
    /* the stream of another context */
    stub_set_stream(S2, 2, 0, NULL);
    v.SetStream(H, S2);
    g = gemm(1, 0, 1536, 128, 4096); expect_forwarded("a stream of another context", &g, R_CONTEXT);
    v.SetStream(H, S1);
    /* another context current */
    stub_set_context(3);
    g = gemm(1, 0, 1536, 128, 4096); expect_forwarded("another context current", &g, R_CONTEXT);
    stub_set_context(0);
    /* 64-bit sizes beyond 32 bits, batches */
    take();
    const float one = 1.0f, zero = 0.0f;
    const Counts c0 = counts(API_GEMMEX64);
    v.GemmEx64(H, CUBLAS_OP_T, CUBLAS_OP_N, 1LL << 31, 4, 1536, &one, DEV(1), CUDA_R_16BF, 1536, DEV(2), CUDA_R_16BF,
               1536, &zero, DEV(3), CUDA_R_32F, 1LL << 31, CUBLAS_COMPUTE_32F, CUBLAS_GEMM_DEFAULT);
    take();
    const Counts c1 = counts(API_GEMMEX64);
    CHECK(count("gemmex64 ") == 1 && count("launch") == 0 && (!rt_counters || c1.v[4 + R_RANGE] - c0.v[4 + R_RANGE] == 1),
          "cublasGemmEx_64 with m = 2^31: not forwarded");
    const Counts s0 = counts(API_SB);
    v.GemmSB(H, CUBLAS_OP_T, CUBLAS_OP_N, 1536, 512, 1536, &one, DEV(1), CUDA_R_16BF, 1536, 0, DEV(2), CUDA_R_16BF, 1536,
             0, &zero, DEV(3), CUDA_R_32F, 1536, 0, 2, CUBLAS_COMPUTE_32F, CUBLAS_GEMM_DEFAULT);
    take();
    const Counts s1 = counts(API_SB);
    CHECK(count("gemmsb ") == 1 && count("launch") == 0 && (!rt_counters || s1.v[4 + R_BATCH] - s0.v[4 + R_BATCH] == 1),
          "a batch of 2: not forwarded");
}

/* ---- H1: what served calls do ---- */
static void h1_served(void)
{
    /* skinny: NT reads op(A) by elements (the generic kernel), 1536 rows of 16 per CTA */
    G g = gemm(0, 1, 1536, 8, 1920);
    expect_skinny("skinny NT 1536 x 8 x 1920", &g, "vf_bf16_skinny_g_8_16 grid=96,1,1 block=128");
    VfSkArgs a;
    launch_args(line("launch ", 0), &a, sizeof a);
    CHECK(a.m == 1536 && a.n == 8 && a.k == 1920 && a.a_si == 1 && a.a_sl == 1536 && a.b_sl == 8 && a.b_sj == 1 &&
              a.o.alpha == 1.0f && a.o.beta_mode == 0 && a.o.dtype == 0 && a.o.btype == -1 && a.o.ldc == 1536,
          "skinny NT: wrong kernel arguments (m %d n %d k %d a_si %lld a_sl %lld b_sl %lld b_sj %lld)", a.m, a.n, a.k,
          a.a_si, a.a_sl, a.b_sl, a.b_sj);
    /* skinny TN: 16-byte loads */
    g = gemm(1, 0, 1536, 16, 1536);
    expect_skinny("skinny TN 1536 x 16 x 1536", &g, "vf_bf16_skinny_16_8 grid=192,1,1 block=128");
    /* the tensor-core path: one chunk */
    g = gemm(1, 0, 1536, 128, 4096);
    take();
    cublasStatus_t st = call(&g);
    take();
    char buf[128];
    CHECK(st == 0 && count("gemmex ") == 0, "tc 1536 x 128 x 4096: forwarded (status %d)", st);
    const char *al = line("alloc ", 0);
    const long long bytes = atoll(field(al, "bytes=", buf, sizeof buf));
    CHECK(count("alloc ") == 1 && bytes > 0 && bytes <= (32ll << 20), "tc: one allocation of at most 32 MiB (%lld)", bytes);
    CHECK(count("memset ") == 1 && strstr(line("memset ", 0), "words=2"), "tc: the counters not reset once");
    CHECK(count("launch vf_bf16_scale") == 1 && count("launch vf_bf16_epilogue") == 1 &&
              count("launch vf_bf16_fallback_tn") == 1 && count("free ") == 1,
          "tc: not scale, epilogue, fallback, free:\n%s", ev);
    const char *lm = line("ltmatmul ", 0);
    CHECK(count("ltmatmul ") == 1 && strstr(lm, "compute=68 transa=1 transb=0 pmode=0 epilogue=1 alpha=1 beta=0") &&
              strstr(lm, "a=2:256x1536:ld4096:b16:s256") && strstr(lm, "b=2:256x128:ld4096:b16:s256") &&
              strstr(lm, "c=0:1536x128:ld1536:b16:s196608") && strstr(lm, "ws=0 "),
          "tc: the internal GEMM is not fp16, TN, k-slices of 256 in a batch of 16, host scalars, no workspace:\n      %s",
          lm ? lm : "(none)");
    /* order: alloc, memset, scale, ltmatmul, epilogue, fallback, free */
    const char *pa = strstr(ev, "alloc "), *pm = strstr(ev, "memset "), *ps = strstr(ev, "launch vf_bf16_scale"),
               *pl = strstr(ev, "ltmatmul "), *pe = strstr(ev, "launch vf_bf16_epilogue"),
               *pf = strstr(ev, "launch vf_bf16_fallback"), *pr = strstr(ev, "free ");
    CHECK(pa && pm && ps && pl && pe && pf && pr && pa < pm && pm < ps && ps < pl && pl < pe && pe < pf && pf < pr,
          "tc: not in the order allocation, counters, scale, GEMM, epilogue, fallback, free");
    /* chunks: static, at most 32 MiB each (16384 x 1024 x 4096 needs several) */
    g = gemm(1, 0, 16384, 1024, 4096);
    g.ldc = 16384;
    take();
    st = call(&g);
    take();
    const int chunks = count("launch vf_bf16_epilogue");
    al = line("alloc ", 0);
    CHECK(st == 0 && count("alloc ") == 1 && atoll(field(al, "bytes=", buf, sizeof buf)) <= (32ll << 20) && chunks > 1 &&
              count("ltmatmul ") == chunks && count("launch vf_bf16_fallback") == chunks,
          "tc 16384 x 1024 x 4096: %d chunks, %d internal GEMMs, allocation %s", chunks, count("ltmatmul "),
          field(al, "bytes=", buf, sizeof buf));
    /* the same call again: the same chunks (static) */
    char *first = strdup(ev);
    take();
    call(&g);
    take();
    CHECK(count("launch vf_bf16_epilogue") == chunks, "tc 16384 x 1024 x 4096: chunks differ between two calls");
    free(first);
}

/* ---- the paths' rule, pinned: which path serves each class of (n, m k, k), VF_CUBLAS_BF16_TC=1 with the skinny
 * path on. n = 1 goes to 12.9; the skinny path first (n <= 16, or n < 32 with m k < 2^20, where 12.9 runs its
 * sequential kernel); then the tensor-core path for m k >= 2^20 or n >= 32 with 2048 <= k <= 16384; the rest to
 * 12.9, with its reason. Checked through the runtime's counters. A change of any boundary must change this
 * table (VF_BF16_TC_MIN_K=1536, a test build's way of moving the gate, makes it fail). ---- */
static void tc_rule(void)
{
    enum { SK = -1, TC = -2 };
    static const struct {
        int ta, tb, m, n, k, want; /* SK, TC, or the reason it is forwarded for */
        const char *why;
    } rows[] = {
        {1, 0, 1536, 1, 4096, R_SHAPE, "n = 1"},
        {1, 0, 1536, 2, 1536, SK, "n = 2"},
        {1, 0, 1536, 16, 4096, SK, "n = 16, k >= 2048: the skinny path first"},
        {1, 0, 1536, 17, 4096, TC, "n = 17, m k >= 2^20"},
        {1, 0, 1536, 17, 1536, R_SHORT_K, "n = 17, m k >= 2^20, k < 2048"},
        {1, 0, 504, 17, 2048, SK, "n = 17, m k < 2^20: the skinny path"},
        {1, 0, 504, 31, 2048, SK, "n = 31, m k < 2^20: the skinny path"},
        {1, 0, 504, 32, 2048, TC, "n = 32, m k < 2^20: wide"},
        {1, 0, 504, 32, 2040, R_SHORT_K, "n = 32, m k < 2^20, k < 2048"},
        {1, 0, 512, 20, 2048, TC, "n = 20, m k = 2^20 (TN m = 512 is in the skinny path's rule only below n = 17)"},
        {1, 0, 384, 20, 2048, R_SEQ, "n = 20, m k < 2^20, TN m = 384 (12.9 runs gemmSN)"},
        {1, 0, 1536, 64, 2040, R_SHORT_K, "k one step under the gate"},
        {1, 0, 1536, 64, 2048, TC, "k = 2048"},
        {1, 0, 1536, 64, 16384, TC, "k = 16384"},
        {1, 0, 64, 40, 16392, R_K, "k = 16392"},
        {1, 0, 1536, 8, 4104, TC, "TN n = 8, k = 4104 (beyond the skinny path's TN rule), m k >= 2^20"},
        {1, 0, 384, 8, 4096, TC, "TN n = 8, m = 384 (12.9 runs gemmSN), m k >= 2^20"},
        {1, 0, 777, 8, 1536, R_SHORT_K, "TN n = 8, m = 777 (not in the skinny path's TN rule), m k >= 2^20, k < 2048"},
        {1, 0, 384, 8, 1536, R_SEQ, "TN n = 8, m = 384, m k < 2^20"},
        {0, 1, 1536, 8, 1920, SK, "NT n = 8"},
        {0, 1, 1536, 64, 1920, R_SHORT_K, "NT n = 64, k < 2048"},
        {0, 1, 1536, 64, 2048, TC, "NT n = 64, k = 2048"},
        {0, 0, 2048, 128, 2048, TC, "NN n = 128"},
        {0, 0, 2048, 8, 2048, SK, "NN n = 8"},
        {0, 0, 64, 8, 1920, R_DOMAIN, "NN m = 64 n = 8 (outside the skinny path's NN bounds), m k < 2^20"},
        {1, 1, 1536, 48, 4096, TC, "TT n = 48"},
    };
    int (*min_k)(void) = NULL;
    void *rt = dlopen("libvf_cublas_bf16.so", RTLD_NOW | RTLD_NOLOAD);
    if (rt) *(void **)&min_k = dlsym(rt, "vf_bf16_test_tc_min_k");
    CHECK(min_k && min_k() == 2048, "rule: the runtime's shortest k for the tensor-core path is %d, not this table's 2048",
          min_k ? min_k() : -1);
    for (size_t r = 0; r < sizeof rows / sizeof *rows; ++r) {
        G g = gemm(rows[r].ta, rows[r].tb, rows[r].m, rows[r].n, rows[r].k);
        const Counts c0 = counts(API_GEMMEX);
        take();
        const cublasStatus_t st = call(&g);
        take();
        const Counts c1 = counts(API_GEMMEX);
        const int sk = c1.v[1] - c0.v[1] == 1, tc = c1.v[2] - c0.v[2] == 1;
        int why = -1;
        for (int q = 0; q < R_N; ++q)
            if (c1.v[4 + q] - c0.v[4 + q] == 1) why = q;
        const int got = sk ? SK : tc ? TC : why;
        char want[32], seen[32];
        snprintf(want, sizeof want, rows[r].want == SK ? "skinny" : rows[r].want == TC ? "tc" : "forwarded (reason %d)",
                 rows[r].want);
        snprintf(seen, sizeof seen, got == SK ? "skinny" : got == TC ? "tc" : "forwarded (reason %d)", got);
        CHECK(st == 0 && got == rows[r].want && (got != SK && got != TC ? count("gemmex ") == 1 : count("gemmex ") == 0),
              "rule: %s %d x %d x %d (%s): %s, not %s", rows[r].ta ? (rows[r].tb ? "TT" : "TN") : (rows[r].tb ? "NT" : "NN"),
              rows[r].m, rows[r].n, rows[r].k, rows[r].why, seen, want);
    }
}

/* ---- H4: one runtime for both APIs ---- */
static void h4_one_runtime(void)
{
    cublasLtHandle_t lt;
    v.LtCreate(&lt);
    CHECK(stub_module_loads() == 1, "two handles (cuBLAS and cuBLASLt) in one context: %d module loads",
          stub_module_loads());
    /* a cuBLAS handle used as a cuBLASLt handle */
    cublasLtMatmulDesc_t d;
    cublasLtMatrixLayout_t la, lb, lc;
    v.DescCreate(&d, CUBLAS_COMPUTE_32F, CUDA_R_32F);
    const int32_t tb = CUBLAS_OP_T;
    v.DescSet(d, CUBLASLT_MATMUL_DESC_TRANSB, &tb, sizeof tb);
    v.LayoutCreate(&la, CUDA_R_16BF, 1536, 1920, 1536);
    v.LayoutCreate(&lb, CUDA_R_16BF, 8, 1920, 8);
    v.LayoutCreate(&lc, CUDA_R_32F, 1536, 8, 1536);
    const float one = 1.0f, zero = 0.0f;
    take();
    const cublasStatus_t st = v.LtMatmul((cublasLtHandle_t)H, d, &one, DEV(1), la, DEV(2), lb, &zero, DEV(3), lc, DEV(3),
                                         lc, NULL, NULL, 0, S1);
    take();
    CHECK(st == 0 && count("launch vf_bf16_skinny") == 1 && count("ltmatmul handle=") == 0,
          "a cuBLAS handle used as a cuBLASLt handle: not served (%d launches, %d forwarded)",
          count("launch vf_bf16_skinny"), count("ltmatmul handle="));
    v.LayoutDestroy(la);
    v.LayoutDestroy(lb);
    v.LayoutDestroy(lc);
    v.DescDestroy(d);
}

/* ---- two devices of different compute capability in one process: decided per context's device ---- */
static void mixed_devices(void)
{
    stub_set_device(1, 8, 0); /* the stand-in's context 1 is on device 1, now an sm_80 card */
    stub_set_context(1);
    cublasHandle_t h1;
    v.Create(&h1);
    v.SetStream(h1, S2);
    stub_set_stream(S2, 1, 0, NULL);
    const float one = 1.0f, zero = 0.0f;
    for (int round = 0; round < 2; ++round) { /* the same thread, alternating, at every call */
        stub_set_context(1);
        take();
        const Counts c0 = counts(API_GEMMEX);
        v.GemmEx(h1, CUBLAS_OP_N, CUBLAS_OP_T, 1536, 8, 1920, &one, DEV(1), CUDA_R_16BF, 1536, DEV(2), CUDA_R_16BF, 8, &zero,
                 DEV(3), CUDA_R_32F, 1536, CUBLAS_COMPUTE_32F, CUBLAS_GEMM_DEFAULT);
        take();
        const Counts c1 = counts(API_GEMMEX);
        CHECK(count("launch ") == 0 && count("gemmex ") == 1 && (!rt_counters || c1.v[4 + R_CONTEXT] - c0.v[4 + R_CONTEXT] == 1),
              "mixed devices, round %d: a call in the sm_80 device's context is not forwarded", round);
        stub_set_context(0);
        G g = gemm(0, 1, 1536, 8, 1920);
        expect_skinny("mixed devices: a call in the V100's context, between calls in the other's", &g,
                      "vf_bf16_skinny_g_8_16");
    }
    stub_set_context(1);
    G g = gemm(0, 1, 1536, 8, 1920); /* the V100's handle while the other device's context is current */
    expect_forwarded("mixed devices: the V100's handle with the sm_80 device's context current", &g, R_CONTEXT);
    stub_set_context(0);
    stub_set_device(1, 7, 0);
}

/* ---- cuBLASLt arguments that the skinny path must leave to 12.9 (review F1, F2) ---- */
static void lt_left_to_129(void)
{
    cublasLtHandle_t lt;
    v.LtCreate(&lt);
    cublasLtMatmulDesc_t d;
    cublasLtMatrixLayout_t la, lb, lc;
    v.DescCreate(&d, CUBLAS_COMPUTE_32F, CUDA_R_32F);
    const int32_t tb = CUBLAS_OP_T;
    v.DescSet(d, CUBLASLT_MATMUL_DESC_TRANSB, &tb, sizeof tb);
    v.LayoutCreate(&la, CUDA_R_16BF, 1536, 1920, 1536);
    v.LayoutCreate(&lb, CUDA_R_16BF, 8, 1920, 8);
    v.LayoutCreate(&lc, CUDA_R_32F, 1536, 8, 1536);
    const float one = 1.0f, zero = 0.0f;
    /* attr: a configuration attribute set to value on top of what cublasLtMatmulAlgoInit leaves (-1: none) */
    static const struct {
        const char *what;
        int32_t id; /* -1: no algorithm */
        int attr;
        uint32_t value;
        int null_c, null_ws, served;
    } cases[] = {
        {"no algorithm", -1, -1, 0, 0, 0, 1},
        {"algorithm id 16 as cublasLtMatmulAlgoInit leaves it (12.9's heuristic)", 16, -1, 0, 0, 0, 1},
        {"algorithm id 11", 11, -1, 0, 0, 0, 0},
        {"algorithm id 16, 4 splits of k", 16, CUBLASLT_ALGO_CONFIG_SPLITK_NUM, 4, 0, 0, 0},
        {"algorithm id 16, split-K count 0", 16, CUBLASLT_ALGO_CONFIG_SPLITK_NUM, 0, 0, 0, 0},
        {"algorithm id 16, tile 5", 16, CUBLASLT_ALGO_CONFIG_TILE_ID, 5, 0, 0, 0},
        {"algorithm id 16, reduction scheme 1", 16, CUBLASLT_ALGO_CONFIG_REDUCTION_SCHEME, 1, 0, 0, 0},
        {"algorithm id 16, CTA swizzling 1", 16, CUBLASLT_ALGO_CONFIG_CTA_SWIZZLING, 1, 0, 0, 0},
        {"algorithm id 16, custom option 1", 16, CUBLASLT_ALGO_CONFIG_CUSTOM_OPTION, 1, 0, 0, 0},
        {"algorithm id 16, stages id 3", 16, CUBLASLT_ALGO_CONFIG_STAGES_ID, 3, 0, 0, 0},
        {"algorithm id 16, inner shape id 1", 16, CUBLASLT_ALGO_CONFIG_INNER_SHAPE_ID, 1, 0, 0, 0},
        {"algorithm id 16, cluster shape id 1", 16, CUBLASLT_ALGO_CONFIG_CLUSTER_SHAPE_ID, 1, 0, 0, 0},
        {"no C descriptor", -1, -1, 0, 1, 0, 0},
        {"no workspace, with a size of 32 MiB", -1, -1, 0, 0, 1, 0},
    };
    for (size_t i = 0; i < sizeof cases / sizeof *cases; ++i) {
        cublasLtMatmulAlgo_t algo;
        memset(&algo, 0, sizeof algo);
        if (cases[i].id >= 0)
            cublasLtMatmulAlgoInit(lt, CUBLAS_COMPUTE_32F, CUDA_R_32F, CUDA_R_16BF, CUDA_R_16BF, CUDA_R_32F, CUDA_R_32F,
                                   cases[i].id, &algo);
        if (cases[i].attr == CUBLASLT_ALGO_CONFIG_CLUSTER_SHAPE_ID)
            algo.data[7] |= (uint64_t)cases[i].value << 32;
        else if (cases[i].attr >= 0)
            algo.data[cases[i].attr] = cases[i].value;
        take();
        v.LtMatmul(lt, d, &one, DEV(1), la, DEV(2), lb, &zero, DEV(3), cases[i].null_c ? NULL : lc, DEV(3), lc,
                   cases[i].id < 0 ? NULL : &algo, NULL, cases[i].null_ws ? (size_t)32 << 20 : 0, S1);
        take();
        const int served = count("launch vf_bf16_skinny") == 1, forwarded = count("ltmatmul handle=") == 1;
        if (cases[i].served)
            CHECK(served && !forwarded, "cuBLASLt, %s: not served by the skinny path", cases[i].what);
        else
            CHECK(forwarded && !served, "cuBLASLt, %s: not left to 12.9", cases[i].what);
    }
    v.LayoutDestroy(la);
    v.LayoutDestroy(lb);
    v.LayoutDestroy(lc);
    v.DescDestroy(d);
}

/* ---- what a cuBLASLt call that no path takes costs before it is forwarded: the attributes read up to
 * its decision, not the whole allowlist ---- */
static int lt_call_reads(cublasLtMatmulDesc_t d, cublasLtMatrixLayout_t la, cublasLtMatrixLayout_t lb,
                         cublasLtMatrixLayout_t lc, size_t ws, int *forwarded, int *served)
{
    const float one = 1.0f, zero = 0.0f;
    const int r0 = stub_lt_gets();
    take();
    v.LtMatmul((cublasLtHandle_t)H, d, &one, DEV(1), la, DEV(2), lb, &zero, DEV(3), lc, DEV(3), lc, NULL, DEV(9), ws, S1);
    take();
    *forwarded = count("ltmatmul handle=") == 1;
    *served = count("launch vf_bf16_skinny") == 1;
    return stub_lt_gets() - r0;
}
static void lt_reads(void)
{
    cublasLtMatmulDesc_t d, d32;
    cublasLtMatrixLayout_t la, lb, lc, lb64, lc64, la32, lb32, lc32;
    v.DescCreate(&d, CUBLAS_COMPUTE_32F, CUDA_R_32F);
    const int32_t ta = CUBLAS_OP_T;
    const uint32_t e = CUBLASLT_EPILOGUE_BIAS;
    const void *bias = DEV(5);
    v.DescSet(d, CUBLASLT_MATMUL_DESC_TRANSA, &ta, sizeof ta);
    v.DescSet(d, CUBLASLT_MATMUL_DESC_EPILOGUE, &e, sizeof e);
    v.DescSet(d, CUBLASLT_MATMUL_DESC_BIAS_POINTER, &bias, sizeof bias);
    v.LayoutCreate(&la, CUDA_R_16BF, 1536, 1536, 1536);
    v.LayoutCreate(&lb, CUDA_R_16BF, 1536, 8, 1536);
    v.LayoutCreate(&lc, CUDA_R_16BF, 1536, 8, 1536);
    v.LayoutCreate(&lb64, CUDA_R_16BF, 1536, 64, 1536);
    v.LayoutCreate(&lc64, CUDA_R_16BF, 1536, 64, 1536);
    v.DescCreate(&d32, CUBLAS_COMPUTE_32F, CUDA_R_32F); /* an fp32 product */
    v.DescSet(d32, CUBLASLT_MATMUL_DESC_TRANSA, &ta, sizeof ta);
    v.LayoutCreate(&la32, CUDA_R_32F, 1536, 1536, 1536);
    v.LayoutCreate(&lb32, CUDA_R_32F, 1536, 8, 1536);
    v.LayoutCreate(&lc32, CUDA_R_32F, 1536, 8, 1536);
    int fwd = 0, srv = 0;
    /* the first call of the process also reads a fresh descriptor's and layout's defaults, once */
    lt_call_reads(d, la, lb, lc, 1u << 20, &fwd, &srv);
    /* PyTorch's F.linear with a bias at n = 8 (its cuBLAS handle as the cuBLASLt handle, C = D, a 1 MiB
     * workspace): 12.9 would not run its sequential kernel for TN with that workspace */
    int reads = lt_call_reads(d, la, lb, lc, 1u << 20, &fwd, &srv);
    CHECK(fwd && reads <= 11, "Lt reads: a call left to 12.9 for its workspace read %d attributes, not at most 11", reads);
    /* n = 64 with only the skinny path on: wider than it takes */
    reads = lt_call_reads(d, la, lb64, lc64, 1u << 20, &fwd, &srv);
    CHECK(fwd && reads <= 7, "Lt reads: an n = 64 call with the skinny path alone read %d attributes, not at most 7", reads);
    /* an fp32 product */
    reads = lt_call_reads(d32, la32, lb32, lc32, 1u << 20, &fwd, &srv);
    CHECK(fwd && reads <= 3, "Lt reads: an fp32 call read %d attributes, not at most 3", reads);
    /* the bias call with a 4 MiB workspace is served: every attribute is read */
    const int all = lt_call_reads(d, la, lb, lc, 4u << 20, &fwd, &srv);
    CHECK(srv && !fwd && all >= 60, "Lt reads: the served call read %d attributes (the allowlist has more than 60)", all);
    printf("note  attribute reads per cuBLASLt call: left to 12.9 for its workspace %d, n = 64 with the skinny path "
           "alone %d, fp32 %d, served %d\n", lt_call_reads(d, la, lb, lc, 1u << 20, &fwd, &srv),
           lt_call_reads(d, la, lb64, lc64, 1u << 20, &fwd, &srv), lt_call_reads(d32, la32, lb32, lc32, 1u << 20, &fwd, &srv),
           all);
    cublasLtMatrixLayout_t ls[] = {la, lb, lc, lb64, lc64, la32, lb32, lc32};
    for (size_t i = 0; i < sizeof ls / sizeof *ls; ++i) v.LayoutDestroy(ls[i]);
    v.DescDestroy(d);
    v.DescDestroy(d32);
}

/* ---- workspaces not 256-byte aligned, and a bias that overlaps D: left to 12.9 ---- */
static void ws_and_bias(void)
{
    /* legacy: a 4 MiB workspace 16 bytes past an aligned address counts as too small (12.9 runs gemmSN there
     * at TN 448 x 8 x 256); aligned, it counts */
    G g = gemm(1, 0, 1536, 8, 1536);
    v.SetWorkspace(H, (char *)DEV(9) + 16, 4u << 20);
    expect_forwarded("TN with a 4 MiB workspace 16 bytes past an aligned address", &g, R_SEQ);
    v.SetWorkspace(H, DEV(9), 4u << 20);
    expect_skinny("TN with an aligned 4 MiB workspace", &g, "vf_bf16_skinny_8_16");
    v.SetStream(H, S1);
    /* cuBLASLt: 12.9 refuses a workspace that is not 256-byte aligned */
    cublasLtMatmulDesc_t d, db;
    cublasLtMatrixLayout_t la, lb, lc;
    v.DescCreate(&d, CUBLAS_COMPUTE_32F, CUDA_R_32F);
    v.DescCreate(&db, CUBLAS_COMPUTE_32F, CUDA_R_32F);
    const int32_t ta = CUBLAS_OP_T;
    const uint32_t e = CUBLASLT_EPILOGUE_BIAS;
    v.DescSet(d, CUBLASLT_MATMUL_DESC_TRANSA, &ta, sizeof ta);
    v.DescSet(db, CUBLASLT_MATMUL_DESC_TRANSA, &ta, sizeof ta);
    v.DescSet(db, CUBLASLT_MATMUL_DESC_EPILOGUE, &e, sizeof e);
    v.LayoutCreate(&la, CUDA_R_16BF, 1536, 1536, 1536);
    v.LayoutCreate(&lb, CUDA_R_16BF, 1536, 8, 1536);
    v.LayoutCreate(&lc, CUDA_R_32F, 1536, 8, 1536);
    const float one = 1.0f, zero = 0.0f;
    static const struct {
        const char *what;
        size_t ws_offset;
        const void *bias; /* NULL: no bias epilogue */
        int served;
    } cases[] = {
        {"cuBLASLt, a 32 MiB workspace at an aligned address", 0, NULL, 1},
        {"cuBLASLt, a 32 MiB workspace 16 bytes past an aligned address", 16, NULL, 0},
        {"cuBLASLt, a 32 MiB workspace 128 bytes past an aligned address", 128, NULL, 0},
        {"cuBLASLt, a bias apart from D", 0, DEV(5), 1},
        {"cuBLASLt, a bias that overlaps D (its fourth column)", 0, (const char *)DEV(3) + 3 * 1536 * 4, 0},
        {"cuBLASLt, a bias that overlaps D's last element", 0, (const char *)DEV(3) + (8 * 1536 - 1) * 4, 0},
    };
    for (size_t i = 0; i < sizeof cases / sizeof *cases; ++i) {
        if (cases[i].bias) v.DescSet(db, CUBLASLT_MATMUL_DESC_BIAS_POINTER, &cases[i].bias, sizeof cases[i].bias);
        take();
        v.LtMatmul((cublasLtHandle_t)H, cases[i].bias ? db : d, &one, DEV(1), la, DEV(2), lb, &zero, DEV(3), lc, DEV(3), lc,
                   NULL, (char *)DEV(9) + cases[i].ws_offset, 32u << 20, S1);
        take();
        const int served = count("launch vf_bf16_skinny") == 1, forwarded = count("ltmatmul handle=") == 1;
        if (cases[i].served)
            CHECK(served && !forwarded, "%s: not served by the skinny path", cases[i].what);
        else
            CHECK(forwarded && !served, "%s: not left to 12.9", cases[i].what);
    }
    v.LayoutDestroy(la);
    v.LayoutDestroy(lb);
    v.LayoutDestroy(lc);
    v.DescDestroy(d);
    v.DescDestroy(db);
}

/* ---- H5: the internal GEMM on the runtime's own handle, with the stream read once ---- */
static void h5_internal_gemm(void)
{
    take();
    v.Create(&H);
    take();
    char rt_lt[64] = "";
    /* the runtime's cuBLASLt handle was made with the context's state (at the first handle) */
    stub_chaos(H, (cudaStream_t)S2);
    v.SetStream(H, S1);
    G g = gemm(1, 0, 1536, 128, 4096);
    take();
    call(&g);
    take();
    char lmbuf[4096] = "", buf[64];
    if (line("ltmatmul ", 0)) snprintf(lmbuf, sizeof lmbuf, "%s", line("ltmatmul ", 0));
    const char *lm = lmbuf[0] ? lmbuf : NULL;
    field(line("chaos ", 0), "handle=", rt_lt, sizeof rt_lt);
    CHECK(lm && rt_lt[0] && !strstr(lm, rt_lt), "H5: the internal GEMM went to the caller's handle");
    CHECK(count("gemmsb ") == 0, "H5: the internal GEMM went through the caller's cuBLAS handle");
    CHECK(lm && !strcmp(field(lm, "stream=", buf, sizeof buf), "0x5101") && strstr(lm, "pmode=0"),
          "H5: the internal GEMM did not keep the stream read once and host scalars: %s", lm ? lm : "(none)");
    int bad = 0;
    for (int i = 0; line("launch ", i); ++i) bad += !strstr(line("launch ", i), "stream=0x5101");
    CHECK(count("chaos ") == 1 && bad == 0, "H5: %d launches did not use the stream read once", bad);
}

/* ---- H6: captured calls: the tensor-core path forwards them before making anything; the skinny
 * path serves them (one kernel, nothing allocated) ---- */
static void h6_captured(void)
{
    CUstream s = (CUstream)0x6101;
    stub_set_stream(s, 0, 77, (CUgraph)0x6001);
    v.SetStream(H, s);
    G g = gemm(1, 0, 1536, 128, 4096);
    const Counts c0 = counts(API_GEMMEX);
    take();
    call(&g);
    take();
    const Counts c1 = counts(API_GEMMEX);
    CHECK(count("gemmex ") == 1 && count("alloc") == 0 && count("launch") == 0 && count("memset") == 0 &&
              count("ltmatmul") == 0,
          "H6: a captured tensor-core call was not forwarded before anything was made:\n%s", ev);
    CHECK(c1.v[4 + R_CAPTURED] - c0.v[4 + R_CAPTURED] == 1, "H6: not counted as a captured call");
    G k = gemm(0, 1, 1536, 8, 1920);
    expect_skinny("H6: a captured skinny call", &k, "vf_bf16_skinny_g_8_16");
    v.SetStream(H, S1);
}

/* ---- H7: cuBLASLt attributes, each outside the supported set ---- */
static void h7_lt_allowlist(void)
{
    cublasLtHandle_t lt;
    v.LtCreate(&lt);
    static const struct {
        int attr, size;
        int64_t value;
    } desc_cases[] = {
        {CUBLASLT_MATMUL_DESC_TRANSC, 4, 1}, {CUBLASLT_MATMUL_DESC_FILL_MODE, 4, 0},
        {CUBLASLT_MATMUL_DESC_BIAS_BATCH_STRIDE, 8, 7}, {CUBLASLT_MATMUL_DESC_EPILOGUE_AUX_POINTER, 8, 0x1000},
        {CUBLASLT_MATMUL_DESC_EPILOGUE_AUX_LD, 8, 64}, {CUBLASLT_MATMUL_DESC_EPILOGUE_AUX_BATCH_STRIDE, 8, 64},
        {CUBLASLT_MATMUL_DESC_ALPHA_VECTOR_BATCH_STRIDE, 8, 64}, {CUBLASLT_MATMUL_DESC_SM_COUNT_TARGET, 4, 40},
        {CUBLASLT_MATMUL_DESC_A_SCALE_POINTER, 8, 0x1000}, {CUBLASLT_MATMUL_DESC_B_SCALE_POINTER, 8, 0x1000},
        {CUBLASLT_MATMUL_DESC_C_SCALE_POINTER, 8, 0x1000}, {CUBLASLT_MATMUL_DESC_D_SCALE_POINTER, 8, 0x1000},
        {CUBLASLT_MATMUL_DESC_AMAX_D_POINTER, 8, 0x1000}, {CUBLASLT_MATMUL_DESC_EPILOGUE_AUX_DATA_TYPE, 4, 2},
        {CUBLASLT_MATMUL_DESC_EPILOGUE_AUX_SCALE_POINTER, 8, 0x1000},
        {CUBLASLT_MATMUL_DESC_EPILOGUE_AUX_AMAX_POINTER, 8, 0x1000}, {CUBLASLT_MATMUL_DESC_FAST_ACCUM, 1, 1},
        {CUBLASLT_MATMUL_DESC_ATOMIC_SYNC_NUM_CHUNKS_D_ROWS, 4, 2},
        {CUBLASLT_MATMUL_DESC_ATOMIC_SYNC_NUM_CHUNKS_D_COLS, 4, 2},
        {CUBLASLT_MATMUL_DESC_ATOMIC_SYNC_IN_COUNTERS_POINTER, 8, 0x1000},
        {CUBLASLT_MATMUL_DESC_ATOMIC_SYNC_OUT_COUNTERS_POINTER, 8, 0x1000},
        {CUBLASLT_MATMUL_DESC_A_SCALE_MODE, 4, 1}, {CUBLASLT_MATMUL_DESC_B_SCALE_MODE, 4, 1},
        {CUBLASLT_MATMUL_DESC_C_SCALE_MODE, 4, 1}, {CUBLASLT_MATMUL_DESC_D_SCALE_MODE, 4, 1},
        {CUBLASLT_MATMUL_DESC_EPILOGUE_AUX_SCALE_MODE, 4, 1}, {CUBLASLT_MATMUL_DESC_D_OUT_SCALE_POINTER, 8, 0x1000},
        {CUBLASLT_MATMUL_DESC_D_OUT_SCALE_MODE, 4, 1},
        /* supported attributes with values outside the supported set */
        {CUBLASLT_MATMUL_DESC_COMPUTE_TYPE, 4, CUBLAS_COMPUTE_32F_PEDANTIC}, {CUBLASLT_MATMUL_DESC_SCALE_TYPE, 4, CUDA_R_16F},
        {CUBLASLT_MATMUL_DESC_POINTER_MODE, 4, 2}, {CUBLASLT_MATMUL_DESC_EPILOGUE, 4, 2},
        {CUBLASLT_MATMUL_DESC_BIAS_DATA_TYPE, 4, CUDA_R_16F},
    };
    static const struct {
        int attr, size;
        int64_t value;
    } layout_cases[] = {{CUBLASLT_MATRIX_LAYOUT_ORDER, 4, 1}, {CUBLASLT_MATRIX_LAYOUT_BATCH_COUNT, 4, 2},
                        {CUBLASLT_MATRIX_LAYOUT_STRIDED_BATCH_OFFSET, 8, 4096},
                        {CUBLASLT_MATRIX_LAYOUT_PLANE_OFFSET, 8, 4096}, {CUBLASLT_MATRIX_LAYOUT_BATCH_MODE, 4, 1}};
    const float one = 1.0f, zero = 0.0f;
    const int nd = sizeof desc_cases / sizeof desc_cases[0], nl = sizeof layout_cases / sizeof layout_cases[0];
    for (int i = -1; i < nd + nl; ++i) {
        cublasLtMatmulDesc_t d;
        cublasLtMatrixLayout_t la, lb, lc;
        v.DescCreate(&d, CUBLAS_COMPUTE_32F, CUDA_R_32F);
        const int32_t tb = CUBLAS_OP_T;
        v.DescSet(d, CUBLASLT_MATMUL_DESC_TRANSB, &tb, sizeof tb);
        v.LayoutCreate(&la, CUDA_R_16BF, 1536, 1920, 1536);
        v.LayoutCreate(&lb, CUDA_R_16BF, 8, 1920, 8);
        v.LayoutCreate(&lc, CUDA_R_32F, 1536, 8, 1536);
        if (i >= 0 && i < nd) {
            if (desc_cases[i].attr == CUBLASLT_MATMUL_DESC_BIAS_DATA_TYPE) { /* matters with a bias only */
                const uint32_t e = CUBLASLT_EPILOGUE_BIAS;
                const void *bias = DEV(5);
                v.DescSet(d, CUBLASLT_MATMUL_DESC_EPILOGUE, &e, 4);
                v.DescSet(d, CUBLASLT_MATMUL_DESC_BIAS_POINTER, &bias, sizeof bias);
            }
            if (desc_cases[i].attr == CUBLASLT_MATMUL_DESC_EPILOGUE) {
                const uint32_t e = (uint32_t)desc_cases[i].value;
                v.DescSet(d, CUBLASLT_MATMUL_DESC_EPILOGUE, &e, 4);
            } else {
                v.DescSet(d, (cublasLtMatmulDescAttributes_t)desc_cases[i].attr, &desc_cases[i].value,
                          (size_t)desc_cases[i].size);
            }
        } else if (i >= nd) {
            v.LayoutSet(la, (cublasLtMatrixLayoutAttribute_t)layout_cases[i - nd].attr, &layout_cases[i - nd].value,
                        (size_t)layout_cases[i - nd].size);
        }
        take();
        v.LtMatmul(lt, d, &one, DEV(1), la, DEV(2), lb, &zero, DEV(3), lc, DEV(3), lc, NULL, NULL, 0, S1);
        take();
        const int served = count("launch vf_bf16_skinny") == 1, forwarded = count("ltmatmul handle=") == 1;
        if (i < 0)
            CHECK(served && !forwarded, "H7: the call with every attribute at its default is not served");
        else
            CHECK(forwarded && !served, "H7: %s attribute %d set to %lld: not forwarded", i < nd ? "descriptor" : "layout",
                  i < nd ? desc_cases[i].attr : layout_cases[i - nd].attr,
                  (long long)(i < nd ? desc_cases[i].value : layout_cases[i - nd].value));
        v.LayoutDestroy(la);
        v.LayoutDestroy(lb);
        v.LayoutDestroy(lc);
        v.DescDestroy(d);
    }
}

int main(int argc, char **argv)
{
    if (argc < 3) {
        printf("usage: host_test DIR all|skinny|off|inject STEP|noruntime\n");
        return 2;
    }
    const char *mode = argv[2];
    /* inject STEP: the stand-in fails the function of that step (the runtime's error handling, as with
     * a driver that refuses) */
    static const char *const steps[][2] = {{"module", "cuModuleLoadData"}, {"alloc", "cuMemAllocFromPoolAsync"},
                                           {"scale", "vf_bf16_scale"},     {"gemm16", "cublasLtMatmul"},
                                           {"epilogue", "vf_bf16_epilogue"}, {"fallback", "vf_bf16_fallback_tn"}};
    const char *inject = !strcmp(mode, "inject") && argc > 3 ? argv[3] : NULL;
    for (int i = 0; inject && i < 6; ++i)
        if (!strcmp(inject, steps[i][0]) && i == 0) stub_fail(steps[i][1], 1); /* at the first handle */
    open_variants(argv[1]);
    if (v.Create(&H)) {
        printf("FAIL  cublasCreate\n");
        return 1;
    }
    open_runtime();
    v.SetStream(H, S1);
    if (!strcmp(mode, "all")) {
        if (!rt_counters) printf("FAIL  not the test build of the runtime\n"), ++failures;
        h1_forwarded();
        h1_served();
        h4_one_runtime();
        lt_left_to_129();
        mixed_devices();
        h6_captured();
        h7_lt_allowlist();
        h5_internal_gemm();
    } else if (!strcmp(mode, "rule")) {
        if (!rt_counters) printf("FAIL  not the test build of the runtime\n"), ++failures;
        tc_rule();
    } else if (!strcmp(mode, "release-gate")) { /* the release runtime, VF_CUBLAS_BF16_TC=1, VF_BF16_TC_MIN_K=1024 */
        G g = gemm(1, 0, 1536, 128, 1536);
        take();
        cublasStatus_t st = call(&g);
        take();
        CHECK(st == 0 && count("gemmex ") == 1 && count("launch") == 0,
              "release gate: TN 1536 x 128 x 1536 (k < 2048) not forwarded with VF_BF16_TC_MIN_K=1024 set");
        g = gemm(1, 0, 1536, 128, 2048);
        take();
        st = call(&g);
        take();
        CHECK(st == 0 && count("gemmex ") == 0 && count("launch vf_bf16_epilogue") == 1,
              "release gate: TN 1536 x 128 x 2048 not served by the tensor-core path");
    } else if (!strcmp(mode, "skinny")) {
        G g = gemm(0, 1, 1536, 8, 16392);
        expect_forwarded("skinny alone, k = 16392", &g, R_DOMAIN);
        g = gemm(0, 1, 16384, 8, 16);
        expect_forwarded("skinny alone, NT m = 16384 k = 16 (slower than 12.9 there)", &g, R_DOMAIN);
        g = gemm(0, 0, 64, 8, 1920);
        expect_forwarded("skinny alone, NN m = 64", &g, R_DOMAIN);
        g = gemm(0, 1, 64, 8, 1920);
        expect_skinny("skinny alone, NT m = 64 k = 1920", &g, "vf_bf16_skinny_g_8_16");
        g = gemm(1, 0, 1536, 8, 1536);
        v.SetWorkspace(H, DEV(9), 1u << 20);
        expect_forwarded("skinny alone, TN with a 1 MiB workspace", &g, R_SEQ);
        v.SetStream(H, S1);
        expect_skinny("skinny alone, TN after cublasSetStream", &g, "vf_bf16_skinny_8_16");
        lt_reads();
        ws_and_bias();
    } else if (!strcmp(mode, "lazy")) { /* VF_CUBLAS_BF16_TC=1: what the runtime makes, and when */
        take(); /* every event since the process started: cublasCreate and cublasSetStream */
        CHECK(count("module load") == 0 && count("pool create") == 0 && count("ltcreate") == 0,
              "lazy: the runtime made something with the handle:\n%s", ev);
        /* a captured tensor-core call first: forwarded, and nothing made */
        CUstream cs = (CUstream)0x6101;
        stub_set_stream(cs, 0, 77, (CUgraph)0x6001);
        v.SetStream(H, cs);
        G g = gemm(1, 0, 1536, 128, 4096);
        take();
        call(&g);
        take();
        CHECK(count("gemmex ") == 1 && count("module load") == 0 && count("pool create") == 0 && count("ltcreate") == 0,
              "lazy: a captured tensor-core call made something:\n%s", ev);
        /* the first skinny call, captured (the stand-in's thread is in global mode): the module alone, loaded in
         * relaxed capture mode, the thread's mode given back before the launch */
        G k = gemm(0, 1, 1536, 8, 1920);
        take();
        call(&k);
        take();
        const char *pr = strstr(ev, "capturemode 2\n"), *pm = strstr(ev, "module load"), *pb = pm ? strstr(pm, "capturemode 0") : NULL,
                   *pl = strstr(ev, "launch vf_bf16_skinny");
        CHECK(count("module load") == 1 && count("pool create") == 0 && count("ltcreate") == 0 && pr && pm && pb && pl &&
                  pr < pm && pm < pb && pb < pl,
              "lazy: the first skinny call did not load the module alone, in relaxed capture mode, before its launch:\n%s",
              ev);
        /* the first eager tensor-core call: the pool and the cuBLASLt handle, in relaxed capture mode, before the
         * workspace's allocation */
        v.SetStream(H, S1);
        take();
        call(&g);
        take();
        const char *ppool = strstr(ev, "pool create"), *plt = strstr(ev, "ltcreate"), *palloc = strstr(ev, "alloc ");
        const char *pr2 = ppool ? NULL : strstr(ev, "capturemode 2\n");
        for (const char *q = ev; ppool && (q = strstr(q, "capturemode 2\n")) && q < ppool; ++q) pr2 = q;
        const char *pb2 = plt ? strstr(plt, "capturemode 0") : NULL;
        CHECK(count("pool create") == 1 && count("ltcreate") == 1 && count("module load") == 0 && pr2 && pr2 < ppool &&
                  ppool < plt && pb2 && palloc && pb2 < palloc && count("gemmex ") == 0,
              "lazy: the first tensor-core call did not make the pool and the cuBLASLt handle, in relaxed capture mode, "
              "before its workspace:\n%s", ev);
        /* a second call: nothing more */
        take();
        call(&g);
        call(&k);
        take();
        CHECK(count("module load") == 0 && count("pool create") == 0 && count("ltcreate") == 0,
              "lazy: later calls made something again:\n%s", ev);
    } else if (!strcmp(mode, "safe")) { /* VF_SAFE=1 with VF_CUBLAS_BF16_TC=1: the tensor-core path serves nothing */
        G g = gemm(1, 0, 1536, 128, 4096);
        expect_forwarded("safe: a tensor-core call", &g, R_DOMAIN);
        g = gemm(1, 0, 16384, 1024, 4096);
        g.ldc = 16384;
        expect_forwarded("safe: a large tensor-core call", &g, R_DOMAIN);
        g = gemm(0, 1, 1536, 8, 1920);
        expect_skinny("safe: a skinny call", &g, "vf_bf16_skinny_g_8_16");
    } else if (!strcmp(mode, "notsafe")) { /* VF_SAFE set to another value than 1, VF_CUBLAS_BF16_TC=1 */
        G g = gemm(1, 0, 1536, 128, 4096);
        take();
        const cublasStatus_t st = call(&g);
        take();
        CHECK(st == 0 && count("gemmex ") == 0 && count("launch vf_bf16_epilogue") == 1,
              "not safe: a tensor-core call was not served (VF_SAFE=%s)", getenv("VF_SAFE") ? getenv("VF_SAFE") : "(unset)");
    } else if (!strcmp(mode, "otherbuild")) { /* STUB_CUBLAS_VERSION set: not the cuBLAS of the rule */
        G g = gemm(0, 1, 1536, 8, 1920);
        expect_forwarded("skinny alone, another cuBLAS build", &g, R_BUILD);
    } else if (!strcmp(mode, "off")) {
        G g = gemm(0, 1, 1536, 8, 1920);
        take();
        call(&g);
        take();
        CHECK(count("gemmex ") == 1 && count("launch") == 0, "no switch: not forwarded");
        CHECK(!dlopen("libvf_cublas_bf16.so", RTLD_NOW | RTLD_NOLOAD) && stub_module_loads() == 0,
              "no switch: the runtime was loaded");
    } else if (!strcmp(mode, "inject") && argc > 3) {
        const char *step = argv[3];
        G g = gemm(1, 0, 1536, 128, 4096);
        if (!strcmp(step, "module")) {
            take();
            const cublasStatus_t st = call(&g);
            take();
            CHECK(st == 0 && count("gemmex ") == 1 && count("launch") == 0, "kernels not loaded: not forwarded");
        } else {
            for (int i = 1; i < 6; ++i)
                if (!strcmp(step, steps[i][0])) stub_fail(steps[i][1], 1);
            take();
            const cublasStatus_t st = call(&g);
            take();
            const int after = !strcmp(step, "fallback");
            if (after)
                CHECK(st == CUBLAS_STATUS_EXECUTION_FAILED && count("gemmex ") == 0 && count("free ") == 1,
                      "%s failed after the output was written: status %d, forwarded %d", step, st, count("gemmex "));
            else
                CHECK(st == 0 && count("gemmex ") == 1 && count("launch vf_bf16_epilogue") == (strcmp(step, "epilogue") ? 0 : 1) &&
                          count("free ") == (strcmp(step, "alloc") ? 1 : 0),
                      "%s failed before the output was written: status %d, forwarded %d:\n%s", step, st, count("gemmex "), ev);
            /* the next call is served again */
            take();
            call(&g);
            take();
            CHECK(count("gemmex ") == 0 && count("launch vf_bf16_epilogue") == 1, "after the failure: not served again");
        }
    } else if (!strcmp(mode, "noruntime")) {
        G g = gemm(0, 1, 1536, 8, 1920);
        take();
        call(&g);
        call(&g);
        take();
        CHECK(count("gemmex ") == 2 && count("launch") == 0, "no runtime: not forwarded");
    } else {
        printf("unknown mode %s\n", mode);
        return 2;
    }
    if (failures) {
        printf("%d checks failed\n", failures);
        return 1;
    }
    printf("ok %s\n", mode);
    return 0;
}
